<template>
	<view class="container">
			<view class="page-body">
				<view class='wrapper'>
					
					<!--如果需要toolbar只显示一行，通过滑动上下切换，可以给toolbar加上这个样式 style="height: 80rpx;overflow-y: auto;" -->
					<view class='toolbar' @click="format">
						<view class="iconfont icon-charutupian" @click="insertImage"></view>
						<view :class="formats.header === 2 ? 'ql-active' : ''" class="iconfont icon-format-header-2"
							data-name="header" :data-value="2"></view>
						<view :class="formats.header === 3 ? 'ql-active' : ''" class="iconfont icon-format-header-3"
							data-name="header" :data-value="3"></view>
						<view :class="formats.bold ? 'ql-active' : ''" class="iconfont icon-zitijiacu" data-name="bold">
						</view>
						<view :class="formats.italic ? 'ql-active' : ''" class="iconfont icon-zitixieti" data-name="italic">	
						</view>
						<view :class="formats.underline ? 'ql-active' : ''" class="iconfont icon-zitixiahuaxian" data-name="underline"></view>
						<!-- 字体删除线 -->
						<view :class="formats.strike ? 'ql-active' : ''" class="iconfont icon-zitishanchuxian" data-name="strike"></view>
						<!-- #ifndef MP-BAIDU -->
						<!-- 左对齐 -->
						<view :class="formats.align === 'left' ? 'ql-active' : ''" class="iconfont icon-zuoduiqi" data-name="align" data-value="left"></view>
						<!-- #endif -->
						<view :class="formats.align === 'center' ? 'ql-active' : ''" class="iconfont icon-juzhongduiqi" data-name="align" data-value="center"></view>
						<view :class="formats.align === 'right' ? 'ql-active' : ''" class="iconfont icon-youduiqi" data-name="align" data-value="right"></view>
						<view :class="formats.align === 'justify' ? 'ql-active' : ''" class="iconfont icon-zuoyouduiqi" data-name="align" data-value="justify"></view>
						<!-- #ifndef MP-BAIDU -->
						<view :class="formats.lineHeight ? 'ql-active' : ''" class="iconfont icon-line-height" data-name="lineHeight" data-value="2"></view>
						<view :class="formats.letterSpacing ? 'ql-active' : ''" class="iconfont icon-Character-Spacing" data-name="letterSpacing" data-value="2em"></view>
						<view :class="formats.marginTop ? 'ql-active' : ''" class="iconfont icon-722bianjiqi_duanqianju" data-name="marginTop" data-value="20px"></view>
						<view :class="formats.marginBottom ? 'ql-active' : ''" class="iconfont icon-723bianjiqi_duanhouju" data-name="marginBottom" data-value="20px"></view>
						<!-- #endif -->
						<view class="iconfont icon-clearedformat" @click="removeFormat"></view>
						<view class="iconfont icon--checklist" data-name="list" data-value="check"></view>
						<view :class="formats.list === 'ordered' ? 'ql-active' : ''" class="iconfont icon-youxupailie"
							data-name="list" data-value="ordered"></view>
						<view :class="formats.list === 'bullet' ? 'ql-active' : ''" class="iconfont icon-wuxupailie"
							data-name="list" data-value="bullet"></view>
						<view :style="{color:fontColor}" class="iconfont icon-text_color" @click="openColorPick"></view>
						<view class="iconfont icon-undo" @click="undo"></view>
						<view class="iconfont icon-redo" @click="redo"></view>
						<view class="iconfont icon-outdent" data-name="indent" data-value="-1"></view>
						<view class="iconfont icon-indent" data-name="indent" data-value="+1"></view>
						<view class="iconfont icon-fengexian" @click="insertDivider"></view>
						<view :class="formats.header === 1 ? 'ql-active' : ''" class="iconfont icon-format-header-1" data-name="header" :data-value="1"></view>
						<view :class="formats.script === 'sub' ? 'ql-active' : ''" class="iconfont icon-zitixiabiao" data-name="script" data-value="sub"></view>
						<view :class="formats.script === 'super' ? 'ql-active' : ''" class="iconfont icon-zitishangbiao" data-name="script" data-value="super"></view>
						<view class="iconfont icon-shanchu" @click="clear"></view>
						<view :class="formats.direction === 'rtl' ? 'ql-active' : ''" class="iconfont icon-direction-rtl" data-name="direction" data-value="rtl"></view>
					</view>
	
					<view class="editor-wrapper">
						<editor id="editor" class="ql-container" placeholder="开始输入..." show-img-size show-img-toolbar
							show-img-resize @statuschange="onStatusChange" :read-only="readOnly" @ready="onEditorReady"
							@input='getCtx'>
						</editor>
					</view>
	
					<!--颜色选择器 -->
					<color-picker ref="colorPicker" @confirm="confirmColor" @cancel="cancelColor"></color-picker>
				</view>
			</view>
		</view>
	
</template>

<script>
	import ColorPicker from './components/color-picker.vue'
	export default {
		components: {
			ColorPicker
		},
		// v-model 实际上就是一个语法糖，相当于执行了 :value="value" @input="value = $event.target.value"
		// 所以在父级使用子组件 修改v-model中的值就可以给编辑器赋初始值
		props: {
			value: {
				type: String,
				default: '',
			}
		},
		data() {
			return {
				readOnly: false,
				formats: {},
				richText: '', // 输出的html结果
				fontColor:'#000000', //字体颜色
			}
		},
		onLoad() {
			// #ifndef MP-BAIDU 
			uni.loadFontFace({
				family: 'Pacifico',
				source: 'url("https://sungd.github.io/Pacifico.ttf")'
			})
			// #endif
		},

		methods: {
			readOnlyChange() {
				this.readOnly = !this.readOnly
			},
			/**
			onEditorReady() {
				// #ifdef MP-BAIDU
				this.editorCtx = requireDynamicLib('editorLib').createEditorContext('editor');
				// #endif

				console.log('ready', this.value)

				// #ifdef APP-PLUS || MP-WEIXIN || H5
				uni.createSelectorQuery().select('#editor').context((res) => {
					this.editorCtx = res.context

					if (this.value) {
						this.editorCtx.setContents({
							html: this.value
						})
					}
				}).exec()
				// #endif
			},
			**/

			onEditorReady() {
				// 富文本节点渲染完成
				const query = uni.createSelectorQuery().in(this)
				query.select('#editor').context((res) => {
					this.editorCtx = res.context

					// console.log('[onEditorReady]editor,value:', this.value)
					if (this.value) {
						this.editorCtx.setContents({
							html: this.value
						})
					}
				}).exec(this)
			},
			undo() {
				this.editorCtx.undo()
			},
			redo() {
				this.editorCtx.redo()
			},
			
			// toolbar按钮的统一点击事件
			format(e) {
				let {
					name,
					value,
					handler
				} = e.target.dataset
				if (!name) return
				
				if(name == 'color') return this.openColorPick()

				this.editorCtx.format(name, value)
			},
			
			onStatusChange(e) {
				const formats = e.detail
				this.formats = formats
			},
			insertDivider() {
				this.editorCtx.insertDivider({
					success: function() {
						// console.log('insert divider success')
					}
				})
			},
			clear() {
				uni.showModal({
					title: '清空编辑器',
					content: '确定清空编辑器全部内容？',
					success: res => {
						if (res.confirm) {
							this.editorCtx.clear({
								success: function(res) {
									// console.log("clear success")
								}
							})
						}
					}
				})
			},
			
			removeFormat() {
				this.editorCtx.removeFormat()
			},
			insertDate() {
				const date = new Date()
				const formatDate = `${date.getFullYear()}/${date.getMonth() + 1}/${date.getDate()}`
				this.editorCtx.insertText({
					text: formatDate
				})
			},

			// 失去焦点时，获取富文本的内容
			// 子组件中使用 $emit('input', value) 自定义事件来更新值时，事件名必须为 input
			// v-model 实际上就是一个语法糖，相当于执行了 :value="value" @input="value = $event.target.value"
			getCtx(e) {
				this.richText = e.detail.html
				// 将富文本内容传递给父级
				this.$emit('input', e.detail.html)
			},

			// 获取编辑器的内容
			getContent() {
				this.editorCtx.getContents({
					success: res => {
						// console.log('editor content', res.html)
						return res
					}
				});
			},
			
			openColorPick(){
				 this.$refs.colorPicker.open()
			},
			
			// 颜色选择器的确认事件 e.hex 返回的是16进制颜色，如#cccccc
			confirmColor(e){
				this.fontColor = e.hex
				this.editorCtx.format('color', e.hex)
			},
			
			// 颜色选择器的取消事件
			cancelColor(e){
				// console.log('cancel color:', e)
			},

			// 上传图片
			insertImage() {
				uni.showToast({ title: '正在调起相册...', icon: 'none' });
				uni.chooseImage({
					count: 1,
					success: (res) => {
						let file = res.tempFilePaths[0];
						uni.showLoading({ title: '正在上传...', mask: true });
						
						// 兼容判断 vk 对象
						let vkObj = uni.vk || getApp().globalData.vk || this.$vk;
						if (!vkObj) {
							uni.hideLoading();
							return uni.showModal({ content: '严重错误：未找到全局 vk 对象' });
						}

						vkObj.callFunctionUtil.uploadFile({
							title: '执行反馈截图',
							file: file,
							needSave: true,
							success: (uploadRes) => {
								uni.hideLoading();
								this.editorCtx.insertImage({
									src: uploadRes.url,
									alt: '图像',
									width: '100%',
									height: 'auto',
									success: function() {
										uni.showToast({ title: '插入成功', icon: 'success' });
									}
								})
							},
							fail: (err) => {
								uni.hideLoading();
								uni.showModal({ content: '上传失败: ' + JSON.stringify(err) });
							}
						});
					},
					fail: (err) => {
						uni.hideLoading();
						if (err.errMsg && (err.errMsg.indexOf('cancel') === -1)) {
							uni.showModal({ title: '相册唤起失败', content: JSON.stringify(err) });
						}
					}
				})
			}
		}
	}
</script>


<style>
	@import "./editor.css";

	.container {
		width: 100%;
		background-color: #f7f7f7;
	}

	.page-body {
		/* height: calc(100vh - var(--window-top) - var(--status-bar-height)); */
	}

	.wrapper {
		/* height: 100%; */
	}

	.editor-wrapper {
		/* height: calc(100vh - var(--window-top) - var(--status-bar-height) - 140px); */
		min-height: 300rpx;
		background: #fff;
		border: 1px solid #dadbde;
		border-radius: 6rpx;
		margin-bottom: 10rpx;
	}

	.iconfont {
		display: inline-block;
		padding: 8px 8px;
		width: 24px;
		height: 24px;
		cursor: pointer;
		font-size: 20px;
	}

	.toolbar {
		box-sizing: border-box;
		border-bottom: 0;
		font-family: 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
	}

	.ql-container {
		box-sizing: border-box;
		padding: 12px 15px;
		width: 100%;
		min-height: 30vh;
		height: 100%;
		margin-top: 10px;
		font-size: 16px;
		line-height: 1.5;
	}

	.ql-active {
		color: #06c;
	}
</style>
